  }

  /**
   * Adjust EC block indices, it will remove the element of adjustList from
   * indices.
   * @param adjustList the list of indexes to remove, which must be sorted in
   *                   ascending order.
   */
  public void adjustIndices(List<Integer> adjustList) {
    if (adjustList.isEmpty()) {
      return;
    }

    byte[] newIndices = new byte[indices.length - adjustList.size()];
    for (int i = 0, j = 0, k = 0; i < indices.length; ++i) {
      if (j < adjustList.size() && i == adjustList.get(j)) {
        j++;
        continue;
      }
      newIndices[k++] = indices[i];
    }
    this.indices = newIndices;
  }

